// Extraire les champs du formulaire multipart + l'image binaire
const item = $input.first();
const body = item.json.body || item.json;

if (!item.binary || !item.binary.file) {
  throw new Error('Aucun fichier reçu — vérifier que le front envoie bien un fichier "file" en multipart/form-data');
}

return [{
  json: {
    user_id:        body.user_id        || '',
    account_id:     body.account_id     || '',
    category_hint:  body.category_hint  || 'operations',
    period_start:   body.period_start   || '',
    period_end:     body.period_end     || '',
    directive:      body.directive      || '',
    image_base64:   item.binary.file.data,
    image_mime:     item.binary.file.mimeType || 'image/jpeg'
  }
}];

const metadata  = $('Set Metadata').first().json;
const categories = $('Fetch Categories').all().map(i => i.json);
const mappings   = $('Fetch Mapping').all().map(i => i.json);
const batchId    = $('Create Batch').first().json.id;

const catList = categories
  .map(c => `- ${c.name} (id: ${c.id}, type: ${c.flow_type})`)
  .join('\n');

const mapList = mappings
  .map(m => `- "${m.keyword}" → category_id: ${m.category_id}`)
  .join('\n');

const directive = metadata.directive
  ? `\nDIRECTIVE SPÉCIFIQUE : ${metadata.directive}`
  : '';

const prompt = `Tu es un assistant spécialisé dans l'analyse de relevés bancaires français.
Analyse cette capture d'écran et extrais TOUTES les transactions visibles.

PÉRIODE : du ${metadata.period_start} au ${metadata.period_end}${directive}

CATÉGORIES DISPONIBLES :
${catList}

TABLE DE CORRESPONDANCE (marchands connus → catégorie) :
${mapList.length > 0 ? mapList : '(aucune correspondance définie pour l\'instant)'}

RÈGLES :
- Extrais uniquement les transactions explicitement visibles sur l'image
- Montants débités = dépenses (flow_type: "expense"), crédits = revenus (flow_type: "income")
- Virements vers épargne personnelle → flow_type: "savings"
- Virements entre comptes propres → flow_type: "transfer"
- En cas de doute sur un chiffre ou une date : confidence_score < 0.7
- Utilise les category_id de la liste ci-dessus quand la correspondance est évidente

RÉPONDS UNIQUEMENT avec un tableau JSON valide (rien avant ni après) :
[
  {
    "date": "YYYY-MM-DD",
    "amount": 45.90,
    "flow_type": "expense",
    "raw_label": "CB CARREFOUR MARKET 15/05",
    "normalized_label": "Carrefour Market",
    "merchant_name": "Carrefour",
    "suggested_category_id": "uuid-ou-null",
    "confidence_score": 0.95
  }
]`;

return [{ json: { prompt, batch_id: batchId } }];

