const claudeResponse = $('Claude Vision').first().json;
const metadata       = $('Set Metadata').first().json;
const batchId        = $('Create Batch').first().json.id;
const mappings       = $('Fetch Mapping').all().map(i => i.json);

// Vérifier la structure de la réponse Claude
if (!claudeResponse.content || !claudeResponse.content[0] || !claudeResponse.content[0].text) {
  throw new Error('Réponse Claude invalide : ' + JSON.stringify(claudeResponse).substring(0, 300));
}

const rawText = claudeResponse.content[0].text.trim();
let transactions = [];

try {
  // Claude peut répondre avec ```json ... ``` ou directement le tableau
  const clean = rawText
    .replace(/^```json\s*/,  '')
    .replace(/^```\s*/,      '')
    .replace(/\s*```$/,      '')
    .trim();
  transactions = JSON.parse(clean);
  if (!Array.isArray(transactions)) {
    throw new Error('La réponse doit être un tableau JSON, reçu : ' + typeof transactions);
  }
} catch (e) {
  throw new Error(`Échec du parsing Claude : ${e.message}\nRéponse brute : ${rawText.substring(0, 400)}`);
}

if (transactions.length === 0) {
  throw new Error('Claude a retourné 0 transaction — vérifier l\'image ou la période renseignée');
}

// Hash MD5 déterministe pour la déduplication
const crypto = require('crypto');
function externalId(date, amount, label) {
  const str = `${date}|${Math.abs(parseFloat(amount) || 0).toFixed(2)}|${(label || '').trim().toLowerCase()}`;
  return crypto.createHash('md5').update(str).digest('hex');
}

// Résolution catégorie par correspondance de keyword
function resolveCategory(rawLabel, merchantName) {
  const text = `${rawLabel || ''} ${merchantName || ''}`.toLowerCase();
  for (const m of mappings) {
    try {
      const match = m.is_regex
        ? new RegExp(m.keyword, 'i').test(text)
        : text.includes(m.keyword.toLowerCase());
      if (match) return m.category_id;
    } catch (_) {
      continue; // ignorer les regex invalides
    }
  }
  return null;
}

const stagingRows = transactions.map((t, idx) => {
  const resolvedCategory = t.suggested_category_id || resolveCategory(t.raw_label, t.merchant_name);

  const direction =
    t.flow_type === 'income'   ? 'income'       :
    t.flow_type === 'savings'  ? 'savings'      :
    t.flow_type === 'transfer' ? 'transfer_out'  :
    'expense';

  return {
    user_id:                 metadata.user_id,
    import_batch_id:         batchId,
    row_number:              idx + 1,
    raw_date:                t.date,
    raw_amount:              String(t.amount),
    raw_label:               t.raw_label,
    parsed_transaction_date: t.date,
    parsed_amount:           Math.abs(parseFloat(t.amount) || 0),
    direction:               direction,
    target_flow_type:        t.flow_type || 'expense',
    normalized_label:        t.normalized_label || t.raw_label,
    merchant_name:           t.merchant_name    || null,
    target_category_id:      resolvedCategory   || null,
    target_account_id:       metadata.account_id,
    external_id:             externalId(t.date, t.amount, t.raw_label),
    confidence_score:        t.confidence_score ?? 0.8,
    parse_status:            'parsed',
    mapping_status:          resolvedCategory ? 'mapped' : 'pending',
    parsed_ok:               true,
    is_duplicate_candidate:  false,
    review_status:           'pending_review',
    payload:                 t
  };
});

return stagingRows.map(row => ({ json: row }));

// Agréger toutes les lignes staging en un seul tableau pour l'insert batch
const rows = $input.all().map(i => i.json);
return [{ json: { rows, count: rows.length } }];

